var n=`1284-callaloo-soup-dominican-style`;var t=`world-1284`;var a=`DM`;var o=`central-america-caribbean`;var s=4;var l=49;var r={en:`Callaloo Soup Dominican Style`,ua:`Суп калалу по-домінікськи`};var c={en:`Callaloo Soup Dominican Style is a dish from Dominica featuring yellow onion, okra, garlic, spinach. This home-sized recipe records each ingredient at the step where it is used. Spinach replaces callaloo greens; the Dominican island soup has its own regional character.`,ua:`Суп калалу по-домінікськи, страва кухні країни Домініка з такими основними складниками: жовта цибуля, бамія, часник, шпинат. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Шпинат замінює зелень калалу; суп острова Домініка має власні регіональні особливості.`};var m=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,170,`g`],[`okra`,220,`g`],[`garlic`,4,`clove`],[`coconut-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 32 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 32 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:32,i:[[`spinach`,430,`g`],[`pumpkin`,330,`g`],[`coconut-milk`,560,`ml`],[`thyme`,3,`sprig`]]},{en:`Combine the prepared components from earlier steps gently into the intended final mixture; do not add new ingredients.`,ua:`Обережно змішайте раніше підготовлені компоненти в потрібну масу; нових складників на цьому етапі не додавайте.`,t:[`mixing`],m:6,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`table-salt`,null,`to_taste`]]}];var d={slug:n,id:t,country:`DM`,region:o,servings:4,minutes:49,title:r,text:c,steps:m};export{a as country,d as default,t as id,l as minutes,o as region,s as servings,n as slug,m as steps,c as text,r as title};